#include "STM32DeviceController.h"
#include "stm32_hal_compat.h"

// Peripheral handles (typically generated by STM32CubeMX)
static I2C_HandleTypeDef  hi2c1;
static UART_HandleTypeDef huart2;

int main(void) {
    // 1. Reset of all peripherals, Initializes the Flash interface and Systick
    HAL_Init();

    // 2. Instantiate and start DeviceController
    STM32DeviceController controller(&hi2c1, &huart2);
    controller.start();

    // 3. Main processing loop (or FreeRTOS Task)
    while (1) {
        controller.process();
        HAL_Delay(2000); // 2-second acquisition interval
    }

    return 0;
}
